import dlasyf = require( './index' );


// TESTS //

const A = new Float64Array( 4 );
const W = new Float64Array( 4 );
const P = new Int32Array( 2 );
const KB = new Int32Array( 1 );

// The status is numeric; the factor count is a separate mutable Int32 output:
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, W, 2 ); // $ExpectType number
dlasyf( 'column-major', 'lower', 2, 2, KB, A, 2, P, W, 2 ); // $ExpectType number
dlasyf( 101, 121, 2, 2, KB, A, 2, P, W, 2 ); // $ExpectType number
dlasyf( 102, 122, 2, 2, KB, A, 2, P, W, 2 ); // $ExpectType number
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectType number
dlasyf.ndarray( 122, 2, 2, KB, 0, A, -2, -1, 3, P, -1, 1, W, -2, -1, 3 ); // $ExpectType number

// Incorrect enum values and buffer roles remain type errors:
dlasyf( 103, 'upper', 2, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 123, 2, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'F', 'upper', 2, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf.ndarray( 'all', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, W, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, W, W, 2 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, W, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError

// Every required dlasyf argument has its declared role/type:
dlasyf( false, 'upper', 2, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', false, 2, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', false, 2, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, false, KB, A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, [], A, 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, [], 2, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, false, P, W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, [], W, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, [], 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, W, false ); // $ExpectError

// Missing and extra arguments are rejected:
dlasyf(); // $ExpectError
dlasyf( 'row-major' ); // $ExpectError
dlasyf( 'row-major', 'upper' ); // $ExpectError
dlasyf( 'row-major', 'upper', 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2 ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, W ); // $ExpectError
dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, W, 2, 0 ); // $ExpectError

// Every required dlasyf.ndarray argument has its declared role/type:
dlasyf.ndarray( false, 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', false, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, false, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, [], 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, false, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, [], 2, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, false, 1, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, false, 0, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, false, P, 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, [], 1, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, false, 0, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, false, W, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, [], 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, false, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, false, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, false ); // $ExpectError

// Missing and extra arguments are rejected:
dlasyf.ndarray(); // $ExpectError
dlasyf.ndarray( 'upper' ); // $ExpectError
dlasyf.ndarray( 'upper', 2 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1 ); // $ExpectError
dlasyf.ndarray( 'upper', 2, 2, KB, 0, A, 2, 1, 0, P, 1, 0, W, 2, 1, 0, 0 ); // $ExpectError
